package org.example.server.supplier360; import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/supplier-360") public class Supplier360Controller{private final Supplier360Service s;public Supplier360Controller(Supplier360Service s){this.s=s;}@GetMapping("/{id}/summary")public Supplier360Dtos.Summary summary(@PathVariable int id){return s.summary(id);}@GetMapping("/{id}/purchases")public List<Supplier360Dtos.PurchaseRow> purchases(@PathVariable int id){return s.purchases(id);}@GetMapping("/{id}/payments")public List<Supplier360Dtos.PaymentRow> payments(@PathVariable int id){return s.payments(id);}@GetMapping("/{id}/contacts")public List<Supplier360Dtos.ContactRow> contacts(@PathVariable int id){return s.contacts(id);}@PostMapping("/{id}/contacts")public Supplier360Dtos.ContactRow saveContact(@PathVariable int id,@RequestBody Supplier360Dtos.ContactSave d){return s.saveContact(id,d);}@DeleteMapping("/{id}/contacts/{cid}")public Supplier360Dtos.Ok deleteContact(@PathVariable int id,@PathVariable long cid,@RequestParam long rowVersion){s.deleteContact(id,cid,rowVersion);return new Supplier360Dtos.Ok(true,"Deleted");}@GetMapping("/{id}/notes")public List<Supplier360Dtos.NoteRow> notes(@PathVariable int id){return s.notes(id);}@PostMapping("/{id}/notes")public Supplier360Dtos.NoteRow saveNote(@PathVariable int id,@RequestBody Supplier360Dtos.NoteSave d){return s.saveNote(id,d);}@DeleteMapping("/{id}/notes/{nid}")public Supplier360Dtos.Ok deleteNote(@PathVariable int id,@PathVariable long nid,@RequestParam long rowVersion){s.deleteNote(id,nid,rowVersion);return new Supplier360Dtos.Ok(true,"Deleted");}}
